"""Render verdicts as Markdown (for the analyst / ticket) — JSON is just json.dumps of the dict."""


def to_markdown(r: dict) -> str:
    a = r["auth"]
    icon = {"phishing": "🔴", "suspicious": "🟠", "clean": "🟢"}[r["verdict"]]
    L = [f"# {icon} {r['verdict'].upper()} (score {r['score']}/100) — {r['file']}", "",
         "> Lab report generated by PhishDesk-IN on synthetic data.", "",
         f"- **Subject:** {r['subject']}", f"- **From:** `{r['from']}`",
         f"- **SPF/DKIM/DMARC:** {a['spf']} / {a['dkim']} / {a['dmarc']} "
         f"(SPF aligned: {a['spf_aligned']}, DKIM aligned: {a['dkim_aligned']}, d={a['dkim_domain'] or '-'})", "",
         "## Why", "", "| Rule | Weight | Explanation |", "|---|---|---|"]
    L += [f"| {x['rule']} | {x['weight']:+d} | {x['why'].replace('|', '/')} |" for x in r["findings"]] or ["| - | 0 | no findings |"]
    L += ["", "## IOCs", ""]
    L += [f"- URL: `{u}`" for u in r["urls"]] or ["- no URLs"]
    L += [f"- Attachment: `{t['filename']}` sha256 `{t['sha256']}` ({t['size']} B)" for t in r["attachments"]]
    L += ["", "## Recommended action", "",
          {"phishing": "Quarantine, block sender + URLs/hashes at gateway/proxy, search mailboxes for same subject/sender, notify reporter.",
           "suspicious": "Hold for analyst review; detonate URLs in sandbox (e.g. urlscan.io) before release.",
           "clean": "Release; thank reporter."}[r["verdict"]], ""]
    return "\n".join(L)
